CREATE OR REPLACE FUNCTION public.on_job_opened()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'open' and (tg_op = 'INSERT' or old.status is distinct from new.status) then
